html:
{%- from "templates/print_formats/standard_macros.html" import add_header -%}
{{ add_header(0, 1, doc, letter_head, no_letterhead, footer, print_settings) }}
<style>
.al-doc { font-size: 11px; color: #1f2933; }
.al-doc h2 { font-size: 18px; margin: 0 0 2px; letter-spacing: .02em; }
.al-doc .al-sub { color: #52606d; margin-bottom: 12px; }
.al-doc table { width: 100%; border-collapse: collapse; margin: 8px 0 12px; }
.al-doc th { background: #f0f2f5; text-align: left; font-weight: 600; }
.al-doc th, .al-doc td { border: 1px solid #cbd2d9; padding: 4px 6px; vertical-align: top; }
.al-doc .al-grid td { border: none; padding: 2px 8px 2px 0; }
.al-doc .al-label { color: #52606d; width: 22%; }
.al-doc .num { text-align: right; white-space: nowrap; }
.al-doc .al-worse { font-weight: 700; text-decoration: underline; }
.al-doc .al-sign { margin-top: 36px; }
.al-doc .al-sign td { border: none; border-top: 1px solid #52606d; width: 25%; padding-top: 4px; text-align: center; }
.al-doc .al-note { border-left: 3px solid #9aa5b1; padding: 4px 8px; color: #3e4c59; margin: 8px 0; }
</style>
<div class="al-doc">
<h2>{{ _("Off-Hire Note") }}</h2>
<div class="al-sub">{{ doc.name }} &middot; {{ doc.get_formatted("return_datetime") }}{% if doc.is_final_return %} &middot; {{ _("final return") }}{% endif %}</div>
<table class="al-grid">
<tr><td class="al-label">{{ _("Agreement") }}</td><td>{{ doc.rental_agreement }}</td><td class="al-label">{{ _("Customer") }}</td><td><b>{{ doc.customer_name }}</b></td></tr>
<tr><td class="al-label">{{ _("From site") }}</td><td>{{ doc.from_location or "" }}</td><td class="al-label">{{ _("Received at") }}</td><td>{{ doc.to_location }}</td></tr>
<tr><td class="al-label">{{ _("Inspection") }}</td><td>{{ _(doc.inspection_result) }}</td><td class="al-label">{{ _("Inspected by") }}</td><td>{{ frappe.db.get_value("User", doc.inspected_by, "full_name") if doc.inspected_by else "" }}</td></tr>
</table>
<table>
<tr><th>{{ _("Equipment") }}</th><th>{{ _("Out") }}</th><th>{{ _("Condition out / in") }}</th><th class="num">{{ _("Meter out / in") }}</th><th class="num">{{ _("Used") }}</th><th class="num">{{ _("Fuel out / in") }}</th><th class="num">{{ _("Duration") }}</th><th class="num">{{ _("Billable days") }}</th></tr>
{% for row in doc.items %}
<tr><td><b>{{ row.asset }}</b><br>{{ row.asset_name or "" }}</td>
<td>{{ row.get_formatted("dispatch_datetime") }}</td>
<td>{{ _(row.condition_out or "-") }} &rarr; <span class="{{ 'al-worse' if al_condition_changed(row.condition_out, row.condition_in) else '' }}">{{ _(row.condition_in) }}</span></td>
<td class="num">{{ row.meter_reading_out if row.meter_reading_out is not none else "-" }} / {{ row.meter_reading_in if row.meter_reading_in is not none else "-" }}</td>
<td class="num">{{ row.meter_hours_used or "" }}</td>
<td class="num">{{ row.get_formatted("fuel_level_out") if row.fuel_level_out is not none else "-" }} / {{ row.get_formatted("fuel_level_in") if row.fuel_level_in is not none else "-" }}</td>
<td class="num">{{ al_duration(row.elapsed_days) }}</td>
<td class="num">{{ row.billable_days if row.billable_days is not none else "" }}</td></tr>
{% endfor %}
</table>
{% if doc.damages %}
<h4>{{ _("Damage recorded") }}</h4>
<table>
<tr><th>{{ _("Equipment") }}</th><th>{{ _("Severity") }}</th><th>{{ _("Damage") }}</th><th class="num">{{ _("Estimated cost") }}</th><th>{{ _("Chargeable") }}</th></tr>
{% for d in doc.damages %}
<tr><td>{{ d.asset }}</td><td>{{ _(d.severity) }}</td><td>{{ d.damage_description }}</td><td class="num">{{ d.get_formatted("estimated_cost", doc) }}</td><td>{{ _("Yes") if d.chargeable_to_customer else _("No") }}</td></tr>
{% endfor %}
</table>
{% endif %}
{% if doc.inspection_remarks %}<div class="al-note">{{ doc.inspection_remarks }}</div>{% endif %}
<table class="al-sign"><tr><td>{{ _("Received by (yard)") }}</td><td>{{ _("Inspected by") }}</td><td>{{ _("Customer representative") }}</td><td>{{ _("Date") }}</td></tr></table>
</div>
